const PREFIX=`kana:${new URL(self.registration.scope).pathname}:`;
const CACHE=PREFIX+'v2-google-sync';
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./styles.css','./app.mjs','./content.mjs','./engine.mjs','./sync-core.mjs','./google-sheets.mjs','./google-sync.mjs','./config.mjs','./assets/favicon.svg'])));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(response=>response||new Response('Недоступно без соединения',{status:503}))));});
